};

let body = {
    "nombre_completo": "b",
    "correo": "n",
    "contraseña": "g",
    "id_rol": 16
};

fetch(url, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

